import {validateBackup} from './domain.js';
export const storageDescription='單機模式：資料保存在目前瀏覽器，沒有自動雲端同步。請定期匯出備份；清除瀏覽器資料或更換網址可能使資料無法存取。';
let dbPromise,revision=0;
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('shiti-question-book',1);request.onupgradeneeded=()=>request.result.createObjectStore('book');request.onsuccess=()=>{request.result.onversionchange=()=>request.result.close();resolve(request.result);};request.onerror=()=>reject(Error('無法開啟裝置儲存空間，請確認不是受限制的瀏覽模式。'));request.onblocked=()=>reject(Error('請關閉其他拾題分頁後重試。'));});return dbPromise;}
export async function load(){const database=await db();return new Promise((resolve,reject)=>{const request=database.transaction('book','readonly').objectStore('book').get('state');request.onsuccess=()=>{const record=request.result;revision=record?.revision||0;try{resolve(record?validateBackup(record.data):null);}catch(e){reject(e);}};request.onerror=()=>reject(Error('題庫讀取失敗，請重新載入。'));});}
export async function save(data){const database=await db();await new Promise((resolve,reject)=>{const transaction=database.transaction('book','readwrite'),store=transaction.objectStore('book');let conflict=false;const request=store.get('state');request.onsuccess=()=>{if((request.result?.revision||0)!==revision){conflict=true;transaction.abort();return;}store.put({data,revision:revision+1},'state');};transaction.oncomplete=()=>{revision++;resolve();};transaction.onabort=transaction.onerror=()=>reject(Error(conflict?'題庫已在其他分頁更新，請重新載入後再操作。':transaction.error?.name==='QuotaExceededError'?'裝置儲存空間不足，資料尚未儲存。請先備份並釋放空間。':'資料儲存失敗，請重試；目前輸入仍保留。'));});}
